// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] calldata _tos, uint[] calldata v) public {
        vm.assume(_tos.length > 0);
        vm.assume(v.length == _tos.length);
        // The external call to caddress must succeed for the transfer to not revert;
        // a plain fuzzed address is an EOA, so low-level call to it always succeeds.
        // Thus, the adversarial helper is NOT needed: any fuzzed caddress will make the call succeed.
        // We call transfer and capture the return value.
        (bool ok, bytes memory returndata) = address(c).call(abi.encodeWithSelector(C.transfer.selector, from, caddress, _tos, v));
        require(ok, "call did not succeed");
        bool ret = abi.decode(returndata, (bool));
        assertTrue(ret);
    }
}

