pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint[] memory v) public {
        vm.assume(_tos.length > 0);
        vm.assume(_tos.length == v.length);
        vm.assume(from != address(0));
        vm.assume(caddress != address(0));
        vm.assume(caddress != address(c));
        // Ensure all destination addresses are non-zero and distinct from the contract under test
        for (uint i = 0; i < _tos.length; i++) {
            vm.assume(_tos[i] != address(0));
            vm.assume(_tos[i] != address(c));
        }
        // Deploy a helper that always succeeds on transferFrom
        AlwaysSucceed helper = new AlwaysSucceed();
        bool refResult = c.transfer(from, address(helper), _tos, v);
        assertTrue(refResult == true);
    }
}

contract AlwaysSucceed {
    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }
}

