        // 3. call transfer through the helper as `caddress`
        bool success;
        try c.transfer(from, address(helper), _tos, v) returns (bool returned) {
            success = true;
            // Assert: whenever the call succeeds (does not revert), the return value must be true
            assertTrue(returned);
        } catch {
            // if it reverts, property holds vacuously for this input
        }
    }
}

