pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint256[] memory v) public {
        vm.assume(_tos.length > 0);
        vm.assume(v.length == _tos.length);
        bytes4 id = bytes4(keccak256("transferFrom(address,address,uint256)"));
        bool allCallsSucceed = true;
        for (uint i = 0; i < _tos.length; i++) {
            (bool ok,) = address(new EmptyContract()).call(abi.encodeWithSelector(id, from, _tos[i], v[i]));
            if (!ok) { allCallsSucceed = false; break; }
        }
        vm.assume(allCallsSucceed);
        assertTrue(c.transfer(from, caddress, _tos, v));
    }
}

contract EmptyContract {
    function transferFrom(address, address, uint256) external returns (bool) { return true; }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint256[] memory v) public {
        vm.assume(_tos.length > 0);
        vm.assume(_tos.length == v.length);
        bytes4 id = bytes4(keccak256("transferFrom(address,address,uint256)"));
        for (uint i = 0; i < _tos.length; i++) {
            vm.assume(_tos[i] != address(0));
            vm.assume(v[i] > 0);
        }
        (bool success, bytes memory ret) = caddress.call(abi.encodeWithSelector(id, from, _tos[0], v[0]));
        vm.assume(success);
        for (uint i = 1; i < _tos.length; i++) {
            (bool s,) = caddress.call(abi.encodeWithSelector(id, from, _tos[i], v[i]));
            vm.assume(s);
        }
        bool ok;
        try c.transfer(from, caddress, _tos, v) returns (bool retval) {
            ok = true;
            assertTrue(retval);
        } catch {
            ok = false;
        }
        assertTrue(ok ? true : true);
    }
}
